  { handle: '@la_inteligencia_artificial', nombre: 'Jon Hernandez' },
  { handle: '@gustavo-entrala', nombre: 'Gustavo Entrala' },
  { handle: '@JoaquinBarbera', nombre: 'Joaquin Barbera' },
  { handle: '@RingaTech', nombre: 'Ringa Tech' },
  { handle: '@GeekGuyLab', nombre: 'GeekGuy Lab' }
];
return canales.map(c => ({ json: c }));

const canales = $('Canales').all();
const entradas = $input.all();
const out = [];
for (let i = 0; i < entradas.length; i++) {
  const html = entradas[i].json.data || '';
  const m = html.match(/"channelId":"(UC[0-9A-Za-z_-]{22})"/) || html.match(/"externalId":"(UC[0-9A-Za-z_-]{22})"/) || html.match(/channel\/(UC[0-9A-Za-z_-]{22})/);
  if (!m) continue;
  out.push({ json: { canal: canales[i] ? canales[i].json.nombre : 'Canal', feedUrl: 'https://www.youtube.com/feeds/videos.xml?channel_id=' + m[1] } });
}
return out;

const HORAS = 168;
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j || !j.title) continue;
  const link = j.link || '';
  const vm = link.match(/[?&]v=([0-9A-Za-z_-]{11})/);
  const videoId = vm ? vm[1] : String(j.id||'').replace('yt:video:','');
  if (!videoId) continue;
  const pub = new Date(j.pubDate || j.isoDate || j.date || Date.now());
  if ((Date.now()-pub.getTime())/3600000 > HORAS) continue;
  out.push({ json: { fuente:'YouTube', origen:(j.author||j.creator||'YouTube'), titulo:j.title, link:'https://www.youtube.com/watch?v='+videoId, fecha:pub.toISOString(), texto:String(j.contentSnippet||j.content||'').slice(0,400), videoId:videoId } });
}
return out;

const feeds = [
  { feedUrl:'https://the-decoder.com/feed/' },
  { feedUrl:'https://techcrunch.com/category/artificial-intelligence/feed/' },
  { feedUrl:'https://arstechnica.com/ai/feed/' },
  { feedUrl:'https://www.theverge.com/rss/ai-artificial-intelligence/index.xml' },
  { feedUrl:'https://openai.com/news/rss.xml' },
  { feedUrl:'https://deepmind.google/blog/rss.xml' },
  { feedUrl:'https://huggingface.co/blog/feed.xml' }
];
return feeds.map(f => ({ json: f }));

const HORAS = 168;
function host(l){
  const s = (typeof l==='string') ? l : (l && l.href ? l.href : String(l||''));
  try { return new URL(s).hostname.replace(/^www\./,''); }
  catch(e){ const m = s.match(/https?:\/\/([^\/]+)/); return m ? m[1].replace(/^www\./,'') : ''; }
}
function origenDe(l, titulo){
  const h = host(l);
  if (!h) return 'Fuente';
  const map = {'techcrunch.com':'TechCrunch','theverge.com':'The Verge','arstechnica.com':'Ars Technica','the-decoder.com':'The Decoder','marktechpost.com':'MarkTechPost','venturebeat.com':'VentureBeat','openai.com':'OpenAI','deepmind.google':'Google DeepMind','huggingface.co':'Hugging Face'};
  if (map[h]) return map[h];
  if (h.indexOf('news.google.com')>=0){ const m=(titulo||'').match(/ - ([^-]+)$/); return m?m[1].trim():'Google News'; }
  return h;
}
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const pub = new Date(j.pubDate || j.isoDate || j.date || Date.now());
  if ((Date.now()-pub.getTime())/3600000 > HORAS) continue;
  const rl = j.link;
  const link = (typeof rl==='string'?rl:(rl&&rl.href?rl.href:'')) || j.guid || '';
  if (!link || !j.title) continue;
  out.push({ json: { fuente:'Articulo', origen: origenDe(link, j.title), titulo:j.title, link:link, fecha:pub.toISOString(), texto:String(j.contentSnippet||j.content||'').slice(0,400), videoId:'' } });
}
return out;

const data = $input.first() ? $input.first().json : {};
const hits = data.hits || [];
const out = [];
for (const h of hits) {
  if (!h.title) continue;
  out.push({ json: { fuente:'Hacker News', origen:'Hacker News', titulo:h.title, link: h.url || ('https://news.ycombinator.com/item?id='+h.objectID), fecha: h.created_at || new Date().toISOString(), texto: String(h.story_text||'').slice(0,400), videoId:'' } });
}
return out;

const d = $getWorkflowStaticData('global');
d.pulso_feedbacks = []; d.pulso_intentos = 0; d.pulso_prev_incluidos = []; d.pulso_descartados_sel = [];
const items = $input.all().map(i => i.json).filter(v => v && v.titulo);
const POR_ORIGEN = 25;
const grupos = {};
for (const v of items) { (grupos[v.origen] = grupos[v.origen] || []).push(v); }
let lista = []; let ronda = 0, quedan = true;
while (quedan && lista.length < 160) {
  quedan = false;
  for (const k of Object.keys(grupos)) {
    const g = grupos[k];
    if (ronda < Math.min(g.length, POR_ORIGEN)) { lista.push(g[ronda]); quedan = true; }
  }
  ronda++;
}
const paraModelo = lista.map((v,idx) => ({ id: idx, fuente: v.fuente, origen: v.origen, titulo: v.titulo, resumen: String(v.texto||'').slice(0,200) }));
const prompt = 'Eres el editor de un boletin diario de noticias de IA. Recibes una lista (JSON) de items de varias fuentes. Elige los mas relevantes para alguien que quiere estar al dia en IA, con criterio periodistico y SIN sesgo de origen. MAXIMIZA la diversidad: no elijas mas de 2 items del mismo origen. Criterios: lanzamientos/updates de modelos, benchmarks, productos nuevos, investigacion relevante, y movimientos con impacto practico, de negocio o regulatorio. Prioriza novedad, evita duplicados, hype y clickbait. Incluye al menos 2 videos de YouTube si hay. Devuelve UNICAMENTE un objeto JSON con dos claves: "seleccion" (arreglo de ids elegidos, maximo 8) y "descartados" (arreglo de objetos {id, motivo} con las noticias RELEVANTES que consideraste pero dejaste fuera, cada una con una razon breve; incluye SOLO las que estuvieron cerca de entrar o que alguien podria echar de menos, no la lista entera). Lista: ' + JSON.stringify(paraModelo);
return [{ json: { items: lista, body: { contents: [ { parts: [ { text: prompt } ] } ], generationConfig: { temperature: 0.2, responseMimeType: 'application/json' } } } }];

const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts[0].text) || '{}';
let parsed = {};
try { parsed = JSON.parse(raw); } catch (e) {}
let sel = parsed.seleccion || [];
const items = ($('Body Seleccionar').first().json.items) || [];
try {
  const d = $getWorkflowStaticData('global');
  d.pulso_descartados_sel = (parsed.descartados || []).map(x => {
    const it = (typeof x.id === 'number') ? items[x.id] : null;
    return { titular: it ? (it.titulo || '') : (x.titulo || ('id ' + x.id)), motivo: x.motivo || '' };
  }).filter(o => o.titular);
} catch (e) {}
let eleg = sel.map(id => items[id]).filter(Boolean);
if (eleg.length === 0) eleg = items.slice(0, 8);
const TOTAL = 8, MIN_VIDEOS = 2;
const chosen = new Set(eleg.map(v => v.link));
let videos = eleg.filter(v => v.videoId);
if (videos.length < MIN_VIDEOS) {
  for (const v of items) {
    if (videos.length >= MIN_VIDEOS) break;
    if (v.videoId && !chosen.has(v.link)) { videos.push(v); chosen.add(v.link); }
  }
}
const arts = eleg.filter(v => !v.videoId);
const combinado = videos.concat(arts);
const seen = new Set(); const out = [];
for (const v of combinado) { if (!seen.has(v.link)) { seen.add(v.link); out.push(v); } if (out.length >= TOTAL) break; }
return out.map(v => ({ json: v }));

const items = $input.all().map(i => i.json);
const lista = items.map((v,idx) => ({ id: idx, fuente: v.fuente, origen: v.origen, titulo: v.titulo, link: v.link, contenido: String(v.contenido||v.texto||'').slice(0,6000) }));
const prompt = 'Eres el redactor de un boletin diario de IA. Para cada item recibes su titulo, fuente, link y su contenido (transcripcion de video o texto del articulo). Escribe para cada uno un resumen legible en espanol (es-CL), pensado para leer en el movil sin ver el video ni abrir el articulo. IMPORTANTE: el titular, el resumen y los puntos deben quedar SIEMPRE en espanol; si el contenido de la fuente viene en ingles u otro idioma, traducelo al espanol. Ningun texto de salida puede quedar en ingles. Devuelve unicamente un objeto JSON con la clave resumenes, un arreglo con un objeto por item que tenga: id (el mismo numero que recibiste), titular (claro y directo, sin clickbait), resumen (2 a 4 frases que expliquen que paso y por que importa), y puntos (un arreglo de 2 a 4 strings con los datos o puntos clave mas concretos). Usa solo la informacion del contenido entregado, no inventes. Si el contenido viene vacio, resume a partir del titulo de forma breve. Items: ' + JSON.stringify(lista);
return [{ json: { items: items, body: { contents: [ { parts: [ { text: prompt } ] } ], generationConfig: { temperature: 0.4, responseMimeType: 'application/json' } } } }];

const raw = ($json.candidates && $json.candidates[0] && $json.candidates[0].content && $json.candidates[0].content.parts[0].text) || '{}';
let res = [];
try { const o = JSON.parse(raw); res = o.resumenes || (Array.isArray(o) ? o : []); } catch (e) {}
const items = ($('Body Resumen').first().json.items) || [];
return items.map((v,idx) => {
  const r = res.find(x => x && x.id === idx) || res[idx] || {};
  let resumen = (r.resumen && String(r.resumen).trim()) ? String(r.resumen).trim() : '';
  if (!resumen) { resumen = String(v.texto || v.contenido || '').trim().slice(0,240); }
  return { json: Object.assign({}, v, { titular: r.titular || v.titulo, resumen: resumen, puntos: Array.isArray(r.puntos) ? r.puntos : [] }) };
});

const v = $('Parse seleccion').item.json;
const raw = $json.data || '';
let texto = '';
try { const o = JSON.parse(raw); texto = o.content || o.transcript || ''; } catch (e) { texto = ''; }
texto = String(texto || '').trim();
if (!texto) { texto = String(v.texto || '').trim(); }
return { json: Object.assign({}, v, { contenido: texto.slice(0, 6000) }) };

const v = $('Parse seleccion').item.json;
const raw = $json.data || '';
let texto = String(typeof raw === 'string' ? raw : '').trim();
if (!texto) { texto = String(v.texto || '').trim(); }
return { json: Object.assign({}, v, { contenido: texto.slice(0, 6000) }) };

const items = $('Revision final').all().map(i => i.json);
const d = $getWorkflowStaticData('global');
const feedbacks = d.pulso_feedbacks || [];
const fmt = dd => new Date(dd).toLocaleDateString('es-CL', { day:'2-digit', month:'long' });
const fechaFin = new Date();
const fechaIni = new Date(Date.now() - 7*24*3600*1000);
const lista = items.map((v, idx) => ({ id: idx, origen: v.origen, titular: v.titular || v.titulo, contenido: String(v.contenido || v.texto || '').slice(0, 5000) }));
let instrucciones = '';
if (feedbacks.length) {
  instrucciones = ' INDICACIONES DEL EDITOR (correcciones que DEBES aplicar estrictamente en esta version): ' + feedbacks.map((f,i)=>((i+1)+') '+f)).join('  ') + ' ';
}
const prompt = 'Eres el guionista y locutor de un podcast semanal en espanol sobre IA, para profesionales NO tecnicos (duenos de negocio, gerentes). Conviertes el material de la semana (del ' + fmt(fechaIni) + ' al ' + fmt(fechaFin) + ') en un guion locutado, calido y con criterio, para leer en voz alta. Recibes una lista (JSON) con ORIGEN, TITULAR y CONTENIDO; trabaja sobre el contenido; si viene en ingles, traducelo; TODO en espanol es-CL. CORRECCION DE NOMBRES (critico): el CONTENIDO puede venir de subtitulos automaticos de YouTube con errores de transcripcion en nombres de personas, empresas, productos y siglas (por ejemplo, Jensen Juan en vez de Jensen Huang). La grafia correcta de un nombre se toma SIEMPRE del TITULAR y de fuentes escritas, nunca de como suena en el audio; apoyate ademas en tu conocimiento para escribir bien cada nombre. Nunca escribas un nombre de forma fonetica. Si un nombre aparece solo en el contenido y no puedes confirmar su grafia, describelo de forma generica u omitelo. Esto no es inventar: es corregir errores de transcripcion. Produce un guion autocontenido de 8 a 9 minutos (1300 a 1600 palabras). Prioriza lo genuinamente interesante; descarta lo flojo, repetido o irrelevante (mejor 4 temas buenos que 8 mediocres); de cada tema explica el \"por que me importa\". ESTRUCTURA: 1) saludo + foto de la semana con el rango de fechas; 2) los 3 temas mas importantes a fondo; 3) barrido rapido de 3 a 5 titulares; 4) cierre con 2-3 ideas; 5) despedida. PAUSAS obligatorias: inserta EXACTAMENTE [PAUSA_PUBLICIDAD_1] despues del primer tema a fondo y [PAUSA_PUBLICIDAD_2] antes del cierre, cada una sola en su linea. ESTILO: espanol hablado calido, sin tecnicismos (explica siglas), sin links, numeros faciles de leer, sin emojis ni titulos dentro del texto, no inventes datos.' + instrucciones + ' SALIDA: devuelve UNICAMENTE un objeto JSON con tres claves: "guion" (el texto para leer en voz alta, con las dos marcas de pausa en su linea), "incluidos" (arreglo de {titular, por_que} con los temas que SI entraron y por que) y "descartados" (arreglo de {titular, por_que_no} con los items que recibiste pero NO incluiste, con el motivo). Nada fuera del JSON. Items: ' + JSON.stringify(lista);
return [{ json: { body: { contents: [ { parts: [ { text: prompt } ] } ], generationConfig: { temperature: 0.55, maxOutputTokens: 8192, responseMimeType: 'application/json' } } } }];

const c = $json.candidates && $json.candidates[0] && $json.candidates[0].content;
const raw = (c && c.parts && c.parts[0] && c.parts[0].text) || '';
let o = {};
try { o = JSON.parse(raw); } catch (e) {
  try { const m = String(raw).match(/\{[\s\S]*\}/); o = JSON.parse(m ? m[0] : '{}'); } catch (e2) { o = {}; }
}
const guion = (o.guion != null ? String(o.guion) : String(raw)).trim();
const incluidos = Array.isArray(o.incluidos) ? o.incluidos : [];
const descartados = Array.isArray(o.descartados) ? o.descartados : [];
return [{ json: { guion: guion, incluidos: incluidos, descartados: descartados } }];

const guion = ($input.first() && $input.first().json.guion) || '';
const CUNA1 = 'Una pausa, de la mano de Isaligner: alineadores invisibles con especialistas en ortodoncia, en Providencia y Los Ángeles. Convenios con seguros y facilidades de pago.';
const CUNA2 = 'Antes de terminar: Isaligner, tu sonrisa alineada sin complicarte. Agenda en isaligner punto com o escríbenos en Instagram, arroba isaligner. Te esperamos en Providencia y Los Ángeles.';
let seg1 = guion, seg2 = '', seg3 = '';
const M1 = '[PAUSA_PUBLICIDAD_1]', M2 = '[PAUSA_PUBLICIDAD_2]';
const i1 = guion.indexOf(M1), i2 = guion.indexOf(M2);
if (i1 >= 0 && i2 > i1) {
  seg1 = guion.slice(0, i1);
  seg2 = guion.slice(i1 + M1.length, i2);
  seg3 = guion.slice(i2 + M2.length);
}
const normaliza = s => String(s)
  .replace(/\[PAUSA_PUBLICIDAD_\d\]/g, ' ')
  .replace(/https?:\/\/\S+/g, ' ')
  .replace(/[*_#>|~]+/g, ' ')
  .replace(/[·•]/g, ' ')
  .replace(/\s*\n+\s*/g, ' ')
  .replace(/\s{2,}/g, ' ')
  .trim();
const voice = { stability: 0.5, similarity_boost: 0.75, style: 0.0, use_speaker_boost: true };
const piezas = [
  { tipo: 'narracion', texto: normaliza(seg1) },
  { tipo: 'cuna', texto: CUNA1 },
  { tipo: 'narracion', texto: normaliza(seg2) },
  { tipo: 'cuna', texto: CUNA2 },
  { tipo: 'narracion', texto: normaliza(seg3) }
].filter(p => p.texto && p.texto.length > 0);
const tail = (t, n) => { t = String(t || ''); return t.length > n ? t.slice(-n) : t; };
const head = (t, n) => { t = String(t || ''); return t.length > n ? t.slice(0, n) : t; };
return piezas.map((p, idx) => {
  const prev = idx > 0 ? piezas[idx - 1].texto : '';
  const next = idx < piezas.length - 1 ? piezas[idx + 1].texto : '';
  const body = { text: p.texto, model_id: 'eleven_multilingual_v2', voice_settings: voice };
  if (prev) body.previous_text = tail(prev, 400);
  if (next) body.next_text = head(next, 400);
  return { json: { orden: idx, tipo: p.tipo, texto: p.texto, body: body } };
});

const items = $input.all();
const piezas = $('Partir guion').all().map(p => p.json);
let cortIdx = -1;
for (let i = 0; i < items.length; i++) { if (items[i].json && items[i].json.tipo === 'cortina') { cortIdx = i; break; } }
if (cortIdx < 0) cortIdx = items.length - 1;
const getBuf = async (i) => {
  const bin = (items[i] && items[i].binary) || {};
  const props = Object.keys(bin);
  const prop = props.indexOf('data') >= 0 ? 'data' : props[0];
  if (!prop) return Buffer.alloc(0);
  let b = null;
  try { b = await this.helpers.getBinaryDataBuffer(i, prop); } catch (e) {}
  if ((!b || !b.length) && bin[prop] && bin[prop].data) { try { b = Buffer.from(bin[prop].data, 'base64'); } catch (e) {} }
  return (b && b.length) ? b : Buffer.alloc(0);
};
const cortBuf = await getBuf(cortIdx);
const segIdx = [];
for (let i = 0; i < items.length; i++) { if (i !== cortIdx) segIdx.push(i); }
const partes = [];
for (let k = 0; k < segIdx.length; k++) {
  const tipo = (piezas[k] && piezas[k].tipo) || 'narracion';
  const buf = await getBuf(segIdx[k]);
  if (!buf.length) continue;
  if (tipo === 'cuna') {
    if (cortBuf.length) partes.push(cortBuf);
    partes.push(buf);
    if (cortBuf.length) partes.push(cortBuf);
  } else {
    partes.push(buf);
  }
}
const merged = Buffer.concat(partes);
const fecha = new Date().toISOString().slice(0,10);
let titulares = [];
try { titulares = $('Parse resumen').all().map(p => (p.json && p.json.titular) ? p.json.titular : '').filter(Boolean).slice(0,6); } catch (e) {}
const duracion = Math.round(merged.length * 8 / 128000);
const titulo = 'Pulso IA · ' + fecha;
const descripcion = titulares.length
  ? ('Resumen semanal de inteligencia artificial. En este episodio: ' + titulares.join(' · ') + '.')
  : 'Resumen semanal de inteligencia artificial.';
const out = { json: { fecha: fecha, titulo: titulo, descripcion: descripcion, duracion: duracion, segmentos: segIdx.length, bytes: merged.length } };
if (merged.length) {
  out.binary = { data: await this.helpers.prepareBinaryData(merged, 'episodio_' + fecha + '.mp3', 'audio/mpeg') };
}
return [out];

const z = $now.setZone('America/Santiago');
const manana = z.plus({ days: 1 });
const publish_at = manana.set({ hour: 1, minute: 0, second: 0, millisecond: 0 }).toISO();
const email_at = manana.set({ hour: 8, minute: 0, second: 0, millisecond: 0 }).toISO();
return [{ json: { publish_at, email_at, generado: z.toISO() } }];

const items = $input.all().map(i => i.json);
const lista = items.map((v, idx) => ({ id: idx, origen: v.origen, titular: v.titular || v.titulo, resumen: v.resumen || '', puntos: Array.isArray(v.puntos) ? v.puntos : [], fuente: String(v.contenido || v.texto || '').slice(0, 6000) }));
const prompt = "Eres el editor de verificacion de un boletin semanal de IA en espanol. Para cada item recibes su ORIGEN, TITULAR, RESUMEN y PUNTOS (lo que escribio el redactor) y la FUENTE (texto original). Tu UNICA tarea es comprobar que el titular, el resumen y los puntos NO contradigan la fuente ni afirmen cosas que la fuente no dice: cifras inventadas o cambiadas, hechos que no aparecen, atribuciones falsas, fechas o nombres erroneos. NO juzgues estilo, interes ni redaccion. Se conservador: marca 'dudoso' SOLO cuando haya un problema de veracidad claro y verificable contra la fuente. Si la FUENTE viene vacia o muy corta, no puedes verificar: marca 'ok', salvo que el texto afirme cifras o hechos muy especificos que parezcan inventados. Devuelve UNICAMENTE un objeto JSON, sin texto adicional: {\"veredictos\":[{\"id\":<numero>,\"estado\":\"ok\"|\"dudoso\",\"problema\":\"que esta mal, una frase; vacio si ok\",\"recomendacion\":\"como corregirlo usando solo la fuente; vacio si ok\"}]}. Un objeto por item, con el mismo id que recibiste. Items: " + JSON.stringify(lista);
const body = { model: 'claude-haiku-5-5', max_tokens: 2048, messages: [ { role: 'user', content: prompt } ] };
return [{ json: { items, ronda: 1, body } }];

const items = $('Preparar revision 1').first().json.items;
const resp = $json;
let txt = '';
try { const b = (resp.content || []).find(x => x && x.type === 'text'); txt = b ? b.text : ''; } catch (e) {}
let veredictos = [];
try { const m = txt.match(/\{[\s\S]*\}/); const o = JSON.parse(m ? m[0] : txt); veredictos = o.veredictos || []; } catch (e) { veredictos = []; }
const vmap = {};
veredictos.forEach(v => { if (v && typeof v.id === 'number') vmap[v.id] = v; });
const dudosos = [];
items.forEach((v, idx) => { const ver = vmap[idx]; v._estado = (ver && ver.estado === 'dudoso') ? 'dudoso' : 'ok'; v._problema = ver ? (ver.problema || '') : ''; v._recomendacion = ver ? (ver.recomendacion || '') : ''; if (v._estado === 'dudoso') dudosos.push(idx); });
